style.hiddenContent:
/* Preview frame shared by every view (from Lunch and Learn Simple's simple.css).
   Nothing in here is part of any demo. */
:root {
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: clamp(15px, 0.55vw + 9px, 21px);
  color: #1c1b22;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
}

:focus-visible {
  outline: 3px solid #1f6feb;
  outline-offset: 2px;
}

/* The demo area fills the preview. */
.stage {
  position: relative;
  height: 100vh;
  overflow: hidden;
  background: #fff;
}

/* Note shown by unsupported.js when the browser lacks the feature. */
.unsupported {
  position: absolute;
  left: 0.8rem;
  bottom: 0.8rem;
  z-index: 100;
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  max-width: min(26rem, calc(100% - 1.6rem));
  margin: 0;
  padding: 0.35rem 0.75rem;
  font-size: 0.72rem;
  line-height: 1.4;
  color: #b42318;
  background: rgb(253 233 230 / 0.95);
  border: 1px solid #f1b8b0;
  border-radius: 0.6rem;
  pointer-events: none;
}

.unsupported::before {
  content: '';
  flex: none;
  width: 0.45rem;
  height: 0.45rem;
  background: #e5372b;
  border-radius: 50%;
}

.unsupported b {
  color: #8f1d14;
}

/* Looks only, shared by before and after. The header is sticky on both pages;
   only the shadow differs. */

.stage {
  background: #f8f6f1;
}

.report {
  position: absolute;
  inset: 1.5rem;
  overflow-y: auto;
  background: #fff;
  border: 1px solid #e4dfd4;
  border-radius: 1rem;
}

.hero {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 1.5rem;
  align-items: center;
  padding: 2rem;
  background: linear-gradient(135deg, #f2efff, #fff6ef);
}

.hero h2 {
  margin: 0 0 0.5rem;
  font-size: 1.8rem;
  line-height: 1.15;
}

.hero p {
  margin: 0;
  color: #55536a;
}

.hero img {
  width: 100%;
  height: 10rem;
  object-fit: cover;
  border-radius: 0.9rem;
}

.report-header {
  position: sticky;
  top: 0;
  z-index: 1;
}

.surface {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.9rem 2rem;
  background: #fff;
  border-bottom: 1px solid #e4dfd4;
  transition: box-shadow 0.25s, background-color 0.25s;
}

.surface h3 {
  margin: 0;
  font-size: 1.1rem;
}

.surface nav {
  display: flex;
  gap: 1rem;
  font-size: 0.9rem;
  font-weight: 600;
  color: #77748a;
}

.content {
  max-width: 40rem;
  padding: 1rem 2rem 60vh;
}

.content h4 {
  margin: 1.6rem 0 0.4rem;
  font-size: 1.25rem;
}

.content p {
  line-height: 1.65;
  color: #474553;
}

/* "Show sentinel" toggle (before page only): paints the invisible 1px
   sentinel red. The ring is drawn outside, so it stays 1px tall. */
.sentinel-toggle {
  position: absolute;
  right: 2.4rem;
  bottom: 2.4rem;
  z-index: 5;
  padding: 0.55rem 0.9rem;
  font: inherit;
  font-size: 0.85rem;
  font-weight: 700;
  color: #b42318;
  cursor: pointer;
  background: #fff;
  border: 2px solid #f1b8b0;
  border-radius: 999px;
  box-shadow: 0 8px 20px -10px rgb(0 0 0 / 0.4);
}

.sentinel-toggle[aria-pressed="true"] {
  color: #fff;
  background: #e5372b;
  border-color: #e5372b;
}

.show-sentinel .sentinel {
  position: relative;
  background: #e5372b;
  box-shadow: 0 0 0 1px #e5372b;
}

.show-sentinel .sentinel::after {
  content: "sentinel";
  position: absolute;
  right: 2rem;
  bottom: 3px;
  font-family: ui-monospace, monospace;
  font-size: 0.75rem;
  font-weight: 700;
  color: #e5372b;
}

script.content:
const scroller = document.querySelector('.report');
const header = document.querySelector('.report-header');

// An invisible 1px sentinel right before the header
const sentinel = document.createElement('div');
sentinel.className = 'sentinel';
header.before(sentinel);

const observer = new IntersectionObserver(
  ([entry]) => {
    // Gone above the top edge: the header is stuck.
    // Gone below the bottom edge: not reached yet.
    const box = entry.boundingClientRect;
    const above = box.bottom <= entry.rootBounds.top;
    const stuck = !entry.isIntersecting && above;
    header.classList.toggle('is-stuck', stuck);
  },
  { root: scroller, threshold: 0 }
);

observer.observe(sentinel);

script.hiddenContent:
/*
  Demo helper for the before page, not part of the comparison:
  a toggle (or the S key) that paints the invisible sentinel red.
*/
(function () {
  var stage = document.querySelector('.stage');
  var button = document.createElement('button');
  button.className = 'sentinel-toggle';
  button.textContent = 'Show sentinel';
  button.setAttribute('aria-pressed', 'false');
  stage.append(button);

  function toggle() {
    var on = stage.classList.toggle('show-sentinel');
    button.setAttribute('aria-pressed', String(on));
  }
  button.addEventListener('click', toggle);
  document.addEventListener('keydown', function (e) {
    if ((e.key === 's' || e.key === 'S') && !e.metaKey && !e.ctrlKey && !e.altKey) toggle();
  });
})();
